package com.daxiaamu.dbdown
import java.io.ByteArrayInputStream
import java.security.KeyStore
import java.util.Base64
import javax.net.ssl.*
// Public localhost fixture, never used by production clients or APK signing.
internal object TestTls {
    private val store = KeyStore.getInstance("PKCS12").apply {
        load(ByteArrayInputStream(Base64.getDecoder().decode("")), "fixture-password".toCharArray())
    }
    private val keys = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm()).apply {
        init(store, "fixture-password".toCharArray())
    }
    private val trust = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm()).apply { init(store) }
    val trustManager = trust.trustManagers.filterIsInstance<X509TrustManager>().single()
    val socketFactory = SSLContext.getInstance("TLS").apply { init(keys.keyManagers, trust.trustManagers, null) }.socketFactory
}
